using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18",
        new OpenAIClientOptions
        {
            Endpoint = builder.Configuration["AI:Endpoint"] is string ep ? new Uri(ep) : null,
        },
        builder.Configuration["AI:ApiKey"]
            ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.")));

builder.Services.AddSingleton<ResearchNotes>();
builder.Services.AddSingleton<ResearchTools>();

using var app = builder.Build();

var chatClient = app.Services.GetRequiredService<IChatClient>();
var researchTools = app.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research agent that searches the web for information on a topic, takes notes, and produces a final summary.",
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the WebSearch tool to find relevant information (perform multiple searches with different queries).
        2. Use the AddNote tool to record key findings as you go.
        3. Use the GetNotes tool to review what you've collected.
        4. After gathering enough information, produce a clear, concise summary of your findings.
        Always cite your sources when possible.
        """,
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Options = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [
            AIFunctionFactory.Create(researchTools.WebSearch),
            AIFunctionFactory.Create(researchTools.AddNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        ],
    },
};

Console.WriteLine("Agent is working...\n");

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

