var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Options = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [
            AIFunctionFactory.Create(researchTools.WebSearch),
            AIFunctionFactory.Create(researchTools.AddNote),
            AIFunctionFactory.Create(researchTools.GetNotes),
        ],
    },
};

Console.WriteLine("Agent is working...\n");

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// --- Supporting types ---

public class ResearchNotes
{
    private readonly List<string> _notes = [];
    private readonly Lock _lock = new();

    public void Add(string note)
    {
        lock (_lock) { _notes.Add(note); }
    }

    public IReadOnlyList<string> GetAll()
    {
        lock (_lock) { return [.. _notes]; }
    }
}

public class ResearchTools(ResearchNotes notes)
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        // Use a public search API (DuckDuckGo Instant Answer API as a free fallback)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await Http.GetStringAsync(url);

            // Parse minimal fields from DuckDuckGo JSON response
            using var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract text (main answer)
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}\nURL: {abstractUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) &&
                        item.TryGetProperty("FirstURL", out var firstUrl))
                    {
                        results.Add($"- {text.GetString()}\n  URL: {firstUrl.GetString()}");
                    }
                }
            }

            return results.Count > 0
                ? $"Search results for '{query}':\n\n{string.Join("\n\n", results)}"
                : $"No detailed results found for '{query}'. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try rephrasing.";
        }
    }

    [Description("Adds a research note to the collection. Use this to record key findings.")]
    public string AddNote(
        [Description("The note content to save")] string content,
        [Description("Optional source URL for the note")] string? source = null)
    {
        var note = source is not null ? $"{content} (Source: {source})" : content;
        notes.Add(note);
        return $"Note saved. Total notes: {notes.GetAll().Count}";
    }

    [Description("Retrieves all research notes collected so far.")]
    public string GetNotes()
    {
        var all = notes.GetAll();
        if (all.Count == 0)
            return "No notes recorded yet.";

        return $"Research notes ({all.Count} total):\n" +
               string.Join("\n", all.Select((n, i) => $"{i + 1}. {n}"));
    }
}

